<?php
/** Run through WP-CLI with --skip-plugins=strc-core and STRC_QA_PLUGIN pointing to an isolated candidate. */
if (home_url() !== 'https://staging.swisstrclub.ch' || wp_get_environment_type() !== 'staging') throw new RuntimeException('Staging required');
if (!defined('DOING_AJAX')) define('DOING_AJAX',true);
if (class_exists('SwissTRClub\\Core\\Plugin',false)) throw new RuntimeException('Skip the installed core plugin first');
require rtrim(getenv('STRC_QA_PLUGIN') ?: WP_PLUGIN_DIR.'/strc-core','/').'/strc-core.php';
global $wpdb,$checks;
add_filter('pre_wp_mail',static fn()=>true);
$network=0;add_filter('pre_http_request',static function()use(&$network){$network++;return new WP_Error('qa','External requests disabled');});
SwissTRClub\Core\Roles\RoleManager::install();
SwissTRClub\Core\Forms\FormStore::register();
foreach(['strc_topic','strc_document','strc_album','strc_ad','strc_event']as$type)if(!post_type_exists($type))register_post_type($type,['public'=>false]);
register_taxonomy('strc_region','strc_event');
$prefix='strc_pr_qa_'.bin2hex(random_bytes(6));$users=[];$posts=[];$files=[];$checks=[];
function strc_pr_check(bool $condition,string $label):void{global $checks;$checks[]=['check'=>$label,'passed'=>$condition];if(!$condition)throw new RuntimeException($label);}
function strc_pr_capture(callable $run):array{ob_start();try{$value=$run();ob_end_clean();return ['value'=>$value];}catch(RuntimeException $error){$json=ob_get_clean();if($error->getMessage()==='STRC QA stop')return json_decode($json,true)?:[];throw $error;}}
add_filter('wp_die_ajax_handler',static fn()=>static function(){throw new RuntimeException('STRC QA stop');});
add_filter('wp_die_handler',static fn()=>static function(){throw new RuntimeException('STRC QA stop');});
try{
 foreach(['owner'=>['strc_member'],'other'=>['strc_member'],'moderator'=>['strc_member','strc_forum_moderator','strc_marketplace_moderator','strc_library_administrator']]as$name=>$roles){
  $id=wp_insert_user(['user_login'=>$prefix.'_'.$name,'user_pass'=>wp_generate_password(40,true,true),'user_email'=>$prefix.'_'.$name.'@example.invalid','role'=>'strc_member']);if(is_wp_error($id))throw new RuntimeException('Fixture failed');$users[$name]=(int)$id;foreach($roles as$role)(new WP_User($id))->add_role($role);(new SwissTRClub\Core\Members\MembershipRepository())->syncUser($id);
 }
 add_action('pre_get_users',static function($query)use(&$users){$query->query_vars['include']=array_values($users);});
 foreach(['add_user_metadata','update_user_metadata','delete_user_metadata']as$hook)add_filter($hook,static fn($value,$id)=>in_array((int)$id,$users,true)?$value:true,10,2);
 $endpoint=new SwissTRClub\Core\Community\CommunityEndpoint();$endpoint->registerHooks();$classification=new ReflectionMethod($endpoint,'classification');
 $library=['documentType'=>'magazine','language'=>'de','issue'=>'1','year'=>'2026','id'=>'98765'];wp_set_current_user($users['owner']);
 $denied=strc_pr_capture(fn()=>$classification->invoke($endpoint,$library,'library'));strc_pr_check(($denied['success']??null)===false,'Member cannot bypass magazine creation rights with an id');
 $doc=wp_insert_post(['post_type'=>'strc_document','post_status'=>'publish','post_title'=>$prefix.' report','post_author'=>$users['owner']]);$posts[]=$doc;update_post_meta($doc,'strc_form_classification',['documentType'=>'travel-report']);update_post_meta($doc,'strc_document_access','open');
 $denied=strc_pr_capture(fn()=>$classification->invoke($endpoint,$library,'library',get_post($doc)));strc_pr_check(($denied['success']??null)===false,'Member cannot turn a report into a magazine');
 $regular=$classification->invoke($endpoint,['documentType'=>'travel-report','language'=>'de'],'library',get_post($doc));strc_pr_check($regular['documentType']==='travel-report','Existing member reports remain editable');
 wp_set_current_user($users['moderator']);strc_pr_check($classification->invoke($endpoint,$library,'library')['documentType']==='magazine','Library editor may upload magazines');
 $events=[];for($i=0;$i<7;$i++){$id=wp_insert_post(['post_type'=>'strc_event','post_status'=>'publish','post_title'=>$prefix.' event '.$i,'post_author'=>$users['owner']]);$events[]=$id;$posts[]=$id;update_post_meta($id,'strc_start_at',gmdate('c',time()+($i===6?3600:-10-$i)));}
 $recent=(new ReflectionMethod($endpoint,'galleryEvents'))->invoke($endpoint,true);strc_pr_check(!in_array($events[6],array_column($recent,'id'),true),'Future events excluded from recent upload choices');strc_pr_check(count(array_intersect(array_slice($events,0,5),array_column($recent,'id')))===5,'Latest five begun events selected');
 $album=wp_insert_post(['post_type'=>'strc_album','post_status'=>'publish','post_title'=>$prefix.' legacy album','post_author'=>$users['owner']]);$posts[]=$album;update_post_meta($album,'strc_form_classification',['eventId'=>(string)$events[0],'photographer'=>'Original photographer']);
 $future=wp_insert_post(['post_type'=>'strc_album','post_status'=>'publish','post_title'=>$prefix.' future album','post_author'=>$users['owner']]);$posts[]=$future;update_post_meta($future,'strc_form_classification',['eventId'=>(string)$events[6],'galleryCategory'=>'events']);
 $latest=(new ReflectionMethod($endpoint,'galleryRecent'))->invoke($endpoint);strc_pr_check(in_array($album,array_column($latest['items'],'id'),true),'Legacy event album included without category tag');strc_pr_check(!in_array($future,array_column($latest['items'],'id'),true),'Future event albums excluded');
 $edited=$classification->invoke($endpoint,[],'gallery',get_post($album));strc_pr_check($edited['photographer']==='Original photographer','Album editing preserves the original photographer');
 $topic=wp_insert_post(['post_type'=>'strc_topic','post_status'=>'publish','post_title'=>$prefix.' topic','post_author'=>$users['owner']]);$posts[]=$topic;$reply=wp_insert_comment(['comment_post_ID'=>$topic,'user_id'=>$users['other'],'comment_content'=>'Fixture reply','comment_approved'=>1]);
 $delete=new ReflectionMethod($endpoint,'deleteTopic');wp_set_current_user($users['other']);$denied=strc_pr_capture(fn()=>$delete->invoke($endpoint,$topic));strc_pr_check(($denied['success']??null)===false,'Another member cannot delete a topic');wp_set_current_user($users['owner']);$delete->invoke($endpoint,$topic);strc_pr_check(!get_post($topic)&&!get_comment($reply),'Author deletion removes their topic and replies');
 wp_set_current_user($users['moderator']);$denied=strc_pr_capture(fn()=>$delete->invoke($endpoint,$album));strc_pr_check(($denied['success']??null)===false,'Forum deletion cannot remove an album');
 $ad=wp_insert_post(['post_type'=>'strc_ad','post_status'=>'pending','post_title'=>$prefix.' ad','post_author'=>$users['owner']]);$posts[]=$ad;update_post_meta($ad,'strc_ad_expires_at',time()+86400);$ads=new SwissTRClub\Core\Marketplace\MarketplaceEndpoint();$change=new ReflectionMethod($ads,'changeAd');$change->invoke($ads,'approve',['id'=>(string)$ad]);$change->invoke($ads,'approve',['id'=>(string)$ad]);$notices=get_user_meta($users['owner'],'strc_notifications',true);strc_pr_check(count(array_filter(is_array($notices)?$notices:[],static fn($notice)=>str_contains($notice['title']??'',$prefix.' ad')))===1,'Repeated approval produces one owner notice');
 wp_set_current_user($users['owner']);update_user_meta($users['owner'],'strc_street','QA private street');update_user_meta($users['owner'],'strc_postcode','3000');update_user_meta($users['owner'],'strc_website_preferences',['directory'=>true,'mapStreet'=>true]);$_GET=['operation'=>'list','map'=>'1'];$_SERVER['REQUEST_METHOD']='GET';$directory=strc_pr_capture(fn()=>(new SwissTRClub\Core\Members\MemberDirectoryEndpoint())->respond());strc_pr_check(($directory['success']??false)&&count(array_filter($directory['data']['mapMembers']??[],static fn($member)=>(int)$member['id']===$users['owner']&&$member['position']===null))===1&&$network===0,'Map does not send addresses even with an old street flag');strc_pr_check(!str_contains(wp_json_encode($directory),'QA private street'),'Map response excludes street address');
 $store=new SwissTRClub\Core\Community\PrivateUploadStore();$folder=(new ReflectionMethod($store,'directory'))->invoke($store);if(!is_dir($folder))wp_mkdir_p($folder);
 $original=bin2hex(random_bytes(20));$copy=bin2hex(random_bytes(20));$files=[$folder.'/'.$original,$folder.'/'.$copy];file_put_contents($files[0],'QA original');file_put_contents($files[1],'QA rendition');update_option('strc_web_image_'.$original,['key'=>$copy,'name'=>'qa.jpg','mime'=>'image/jpeg','size'=>12],false);update_post_meta($album,'strc_private_files',[['key'=>$original,'name'=>'qa.jpg','mime'=>'image/jpeg','uploadedAt'=>gmdate('c',strtotime('-5 months'))]]);
 $restrict=static function($query)use($album){if($query->get('post_type')==='strc_album')$query->set('post__in',[$album]);};add_action('pre_get_posts',$restrict);try{(new SwissTRClub\Core\Community\GalleryRetention())->run();}finally{remove_action('pre_get_posts',$restrict);}strc_pr_check(!is_file($files[0])&&is_file($files[1]),'Four-month retention expires only the fixture original and keeps rendition');file_put_contents($files[0],'QA retained original');update_post_meta($album,'strc_private_files',[['key'=>$original,'name'=>'qa.jpg','mime'=>'image/jpeg','retainOriginal'=>true,'uploadedAt'=>gmdate('c',strtotime('-5 months'))]]);add_action('pre_get_posts',$restrict);try{(new SwissTRClub\Core\Community\GalleryRetention())->run();}finally{remove_action('pre_get_posts',$restrict);}strc_pr_check(!is_file($files[0])&&is_file($files[1]),'Legacy retention flag no longer extends the four-month limit');update_post_meta($album,'strc_private_files',[['key'=>$original,'name'=>'qa.jpg','mime'=>'image/jpeg','uploadedAt'=>gmdate('c',strtotime('-2 months'))]]);add_action('pre_get_posts',$restrict);try{(new SwissTRClub\Core\Community\GalleryRetention())->run();}finally{remove_action('pre_get_posts',$restrict);}strc_pr_check(is_file($files[0]),'Newer fixture original remains retained');delete_option('strc_web_image_'.$original);
}finally{
 wp_set_current_user(0);foreach($files as$file)if(is_file($file))unlink($file);foreach($posts as$id)wp_delete_post($id,true);require_once ABSPATH.'wp-admin/includes/user.php';foreach($users as$id){$wpdb->delete($wpdb->prefix.'strc_memberships',['user_id'=>$id]);wp_delete_user($id);}
}
echo wp_json_encode(['checks'=>$checks,'fixtureUsersRemoved'=>count($users),'externalRequests'=>$network]);
